source("h.R")
if (nzchar(Sys.getenv("HOSTILE"))) options(OutDec = ",", scipen = -5, digits = 3, warn = 2)
hx <- function(x) if (is.character(x)) vapply(x, function(s) if (is.na(s)) "NA" else paste(charToRaw(enc2utf8(s)), collapse = ""), "", USE.NAMES = FALSE) else x
show <- function(label, expr) { r <- tr(expr); cat("---", label, "\n"); if (inherits(r, "ERR")) { cat("<", r$cls, "> ", paste(charToRaw(r$msg), collapse=""), "\n") } else print(rapply(list(r), hx, how = "replace")[[1]]) }
src <- "<html><head><title> T\u00e9 \u4e2d </title><meta name='d\u00e9' content='c\u00e9'><base href='http://h/\u00e9/'></head><body><div class='\u00e9a \u00dcB\u00a0c' id='\u00efd' title='\u0130'><p>Caf\u00e9\u00a0au  lait <b>\u4e2d\u6587</b></p><a href='p\u00e9/x?q=\u00fc#\u00f1'>l\u00efnk</a><ul><li>\u00e9t\u00e9<li>b</ul><table><tr><th>N\u00b0<th>prix<tr><td>1<td>1\u00a0234,5<tr><td>2<td>3,25</table><form method='P\u00d6ST' action='\u00e9'><input type='T\u00c9XT' name='n\u00e9' value='v\u00e9'><input type=CHECKBOX><select><option>\u00e9 \u00e9</select></form><div itemscope itemtype='http://t/\u00e9'><span itemprop='n\u00e9m'>v\u00e4l</span></div></div></body></html>"
d <- html_parse(src); dr <- html_parse(charToRaw(src))
show("raw==str", identical(html_serialize(d), html_serialize(dr)))
show("title", html_title(d)); show("meta", html_meta(d)); show("classes", html_classes(html_element(d, "div"))); show("attrs", html_attrs(html_element(d, "div")))
show("sel class", length(html_elements(d, ".\u00e9a"))); show("sel id", length(html_elements(d, "#\u00efd"))); show("sel attr", length(html_elements(d, "[title='\u0130']"))); show("sel attr i", length(html_elements(d, "[class~='\u00dcb' i]")))
show("sel err", html_elements(d, "p.\u00e9\u00e9 >> a")); e <- tr(html_elements(d, "p.\u00e9\u00e9 >> a")); show("sel err pos", e$e$position)
show("text", html_text(html_element(d, "p"))); show("clean", html_text_clean(html_element(d, "p"))); show("strings", html_strings(html_element(d, "p"), trim = TRUE))
show("links", html_links(d, absolute = TRUE)); show("url", html_url(html_element(d, "a")))
show("list", html_list(html_element(d, "ul"))); show("table", html_table(html_element(d, "table"), convert = TRUE, decimal = ",", thousands = " "))
show("table plain", html_table(html_element(d, "table"))); show("cells", html_table_cells(html_element(d, "table"))$text)
show("forms", html_forms(d)); show("microdata", html_microdata(d)); show("markdown", html_markdown(d)); show("serialize", html_serialize(html_element(d, "div"), pretty = TRUE))
show("format", format(html_elements(d, "div, p, a"), width = 20)); show("capture print", capture.output(print(html_elements(d, "div,b"))))
show("info", unclass(html_info(d))[c("nodes","input_bytes","encoding","base_url")]); show("print info", capture.output(print(html_info(d)))); show("print limits", capture.output(print(html_limits()))); show("print doc", capture.output(print(d)))
show("problems", html_problems(html_parse("<p>\u00e9</b>")))
show("limits big", unclass(html_limits(max_memory = 2^40, max_nodes = 123456789))[c("max_memory","max_nodes")])
e <- tr(html_parse(strrep("a", 1234567), limits = html_limits(max_input = 1000000))); show("limit msg", e$msg); show("limit fields", c(e$e$maximum, e$e$observed))
show("fragment ctx", html_info(html_fragment("<p>x", context = "DIV"))$context)
l1 <- "<p class='caf\xe9'>\xe9</p>"; Encoding(l1) <- "latin1"; dl <- html_parse(l1); show("latin1 str", html_serialize(dl)); c1 <- "p.caf\xe9"; Encoding(c1) <- "latin1"; show("latin1 css", length(html_elements(dl, c1)))
a1 <- "caf\xe9"; Encoding(a1) <- "latin1"; show("latin1 attr default", html_attr(html_element(dl, "p"), "x", default = a1))
d2 <- html_parse("<p \u00e9='1' x='2'>"); n1 <- "\xe9"; Encoding(n1) <- "latin1"; show("latin1 attr name", html_attr(html_element(d2, "p"), n1)); show("utf8 attr name", html_attr(html_element(d2, "p"), "\u00e9"))
show("na utf8", html_table(html_element(html_parse("<table><tr><td>\u00e9<td>b</table>"), "table"), header = FALSE, na = a1))
show("tables match", length(html_tables(d, match = "N\u00b0"))); show("tables match latin1", length(html_tables(d, match = a1)))
show("json", html_json_ld(html_parse("<script type='application/ld+json'>{\"n\u00e9\": \"v\u00e9\", \"x\": 1.5}</script>"), parse = TRUE))
show("ctx latin1", tr(html_info(html_fragment("<p>", context = "DIV"))$context))
show("sniff", html_info(html_parse(c(charToRaw("<meta charset=latin1><p>"), as.raw(0xe9))))$encoding)
show("u16", html_text(html_parse(as.raw(c(0xff,0xfe,0x3c,0,0x70,0,0x3e,0,0xe9,0,0x3d,0xd8,0x00,0xde)))))
